SELECT id, account_id, enterprise_id, name, phone, id_card, factory_id, deleted, create_by, create_time, update_by, update_time FROM resident_factory WHERE enterprise_id = CAST(#{enterpriseId} AS CHAR) AND factory_id = #{factoryId} AND id_card = #{idCard} AND deleted = 1
AND id != #{residentId}
ORDER BY id DESC LIMIT 1 FOR UPDATE

SELECT id, account_id, enterprise_id, name, phone, id_card, factory_id, deleted, create_by, create_time, update_by, update_time FROM resident_factory WHERE enterprise_id = CAST(#{enterpriseId} AS CHAR) AND account_id = #{accountId} AND factory_id = #{factoryId} AND deleted = 1
AND id != #{residentId}
ORDER BY id DESC LIMIT 1 FOR UPDATE

SELECT f.*
FROM factory f
WHERE f.id = #{factoryId}
  AND f.enterprise_id = #{enterpriseId}
  AND f.deleted = 1
FOR UPDATE
